package dev.folio.runtime.action

import dev.folio.model.command.AppCommand
import dev.folio.runtime.interaction.LearningInteraction

object LearningCommandBridge {
    fun event(command: AppCommand): LearningInteraction? = when (command) {
        is AppCommand.ShowReadingCheckpoints -> LearningInteraction.ShowReadingCheckpoints(command.activityId, command.visible)
        is AppCommand.OpenReadingConfirmation -> LearningInteraction.OpenReadingConfirmation(command.activityId, command.id, command.expectedVersion)
        is AppCommand.ConfirmReading -> LearningInteraction.ConfirmReading(command.activityId, command.source, command.sentenceId, command.expectedReadingRevision)
        is AppCommand.ClearReadingConfirmation -> LearningInteraction.ClearReadingConfirmation(command.activityId, command.id, command.expectedVersion)
        is AppCommand.AddReadingBookmark -> LearningInteraction.AddReadingBookmark(command.activityId, command.id, command.source, command.sentenceId)
        is AppCommand.RemoveReadingBookmark -> LearningInteraction.RemoveReadingBookmark(command.activityId, command.id, command.expectedCreatedRevision)
        is AppCommand.OpenReadingBookmark -> LearningInteraction.OpenReadingBookmark(command.activityId, command.id, command.expectedCreatedRevision)
        is AppCommand.ShowReadingBookmarks -> LearningInteraction.ShowReadingBookmarks(command.activityId, command.visible)
        is AppCommand.SetPracticeTimerExpanded -> LearningInteraction.SetPracticeTimerExpanded(command.activityId, command.expectedAttempt, command.expectedVersion, command.expanded)
        is AppCommand.StartPracticeTimer -> LearningInteraction.StartPracticeTimer(command.activityId, command.expectedAttempt, command.expectedVersion)
        is AppCommand.PausePracticeTimer -> LearningInteraction.PausePracticeTimer(command.activityId, command.expectedAttempt, command.expectedVersion)
        is AppCommand.ResetPracticeTimer -> LearningInteraction.ResetPracticeTimer(command.activityId, command.expectedAttempt, command.expectedVersion)
        is AppCommand.SetPracticeTimerLimit -> LearningInteraction.SetPracticeTimerLimit(command.activityId, command.expectedAttempt, command.expectedVersion, command.seconds)
        is AppCommand.RestartQuiz -> LearningInteraction.RestartQuiz(command.activityId, command.expectedAttempt)
        is AppCommand.ReviewQuizAttempt -> LearningInteraction.ReviewQuizAttempt(command.activityId, command.attemptNumber, command.questionId)
        is AppCommand.SetAnswerConfidence -> LearningInteraction.SetAnswerConfidence(command.activityId, command.questionId, command.expectedOption, command.expectedConfidence, command.confidence)
        is AppCommand.AcceptRevisionSuggestion -> LearningInteraction.AcceptRevisionSuggestion(command.activityId, command.questionId, command.expectedEvidence)
        is AppCommand.ScheduleRevision -> LearningInteraction.ScheduleRevision(command.activityId, command.questionId, command.delayDays)
        is AppCommand.RecallResponse -> LearningInteraction.RecallResponse(command.activityId, command.expectedText, command.text)
        is AppCommand.RevealRecall -> LearningInteraction.RevealRecall(command.activityId)
        is AppCommand.RateRecall -> LearningInteraction.RateRecall(command.activityId, command.rating)
        is AppCommand.RestartRecall -> LearningInteraction.RestartRecall(command.activityId)
        is AppCommand.QuizQuestion -> LearningInteraction.QuizQuestion(command.activityId, command.questionId)
        is AppCommand.SaveAnnotationDraft -> LearningInteraction.SaveAnnotationDraft(command.activityId, command.draftId, command.draft)
        is AppCommand.CreateAnnotation -> LearningInteraction.CreateAnnotation(command.activityId, command.id, command.source, command.sentenceId, command.kind, command.text)
        is AppCommand.UpdateAnnotation -> LearningInteraction.UpdateAnnotation(command.activityId, command.id, command.expectedText, command.text)
        is AppCommand.RemoveAnnotation -> LearningInteraction.RemoveAnnotation(command.activityId, command.id, command.expectedText)
        is AppCommand.SelectAnswer -> LearningInteraction.SelectAnswer(command.activityId, command.questionId, command.option)
        is AppCommand.SubmitAnswer -> LearningInteraction.SubmitAnswer(command.activityId, command.questionId)
        is AppCommand.ReadingPosition -> LearningInteraction.SetReadingPosition(command.activityId, command.index, command.offset)
        is AppCommand.FocusSentence -> LearningInteraction.FocusSentence(command.activityId, command.sentenceId)
        is AppCommand.Pin -> LearningInteraction.PinComponent(command.componentId, command.pinned)
        is AppCommand.Transform -> LearningInteraction.TransformDiagram(command.activityId, command.zoom, command.panX, command.panY)
        else -> null
    }
    fun command(event: LearningInteraction): AppCommand = when (event) {
        is LearningInteraction.ShowReadingCheckpoints -> AppCommand.ShowReadingCheckpoints(event.activityId, event.visible)
        is LearningInteraction.OpenReadingConfirmation -> AppCommand.OpenReadingConfirmation(event.activityId, event.id, event.expectedVersion)
        is LearningInteraction.ConfirmReading -> AppCommand.ConfirmReading(event.activityId, event.source, event.sentenceId, event.expectedReadingRevision)
        is LearningInteraction.ClearReadingConfirmation -> AppCommand.ClearReadingConfirmation(event.activityId, event.id, event.expectedVersion)
        is LearningInteraction.AddReadingBookmark -> AppCommand.AddReadingBookmark(event.activityId, event.id, event.source, event.sentenceId)
        is LearningInteraction.RemoveReadingBookmark -> AppCommand.RemoveReadingBookmark(event.activityId, event.id, event.expectedCreatedRevision)
        is LearningInteraction.OpenReadingBookmark -> AppCommand.OpenReadingBookmark(event.activityId, event.id, event.expectedCreatedRevision)
        is LearningInteraction.ShowReadingBookmarks -> AppCommand.ShowReadingBookmarks(event.activityId, event.visible)
        is LearningInteraction.SetPracticeTimerExpanded -> AppCommand.SetPracticeTimerExpanded(event.activityId, event.expectedAttempt, event.expectedVersion, event.expanded)
        is LearningInteraction.StartPracticeTimer -> AppCommand.StartPracticeTimer(event.activityId, event.expectedAttempt, event.expectedVersion)
        is LearningInteraction.PausePracticeTimer -> AppCommand.PausePracticeTimer(event.activityId, event.expectedAttempt, event.expectedVersion)
        is LearningInteraction.ResetPracticeTimer -> AppCommand.ResetPracticeTimer(event.activityId, event.expectedAttempt, event.expectedVersion)
        is LearningInteraction.SetPracticeTimerLimit -> AppCommand.SetPracticeTimerLimit(event.activityId, event.expectedAttempt, event.expectedVersion, event.seconds)
        is LearningInteraction.RestartQuiz -> AppCommand.RestartQuiz(event.activityId, event.expectedAttempt)
        is LearningInteraction.ReviewQuizAttempt -> AppCommand.ReviewQuizAttempt(event.activityId, event.attemptNumber, event.questionId)
        is LearningInteraction.SetAnswerConfidence -> AppCommand.SetAnswerConfidence(event.activityId, event.questionId, event.expectedOption, event.expectedConfidence, event.confidence)
        is LearningInteraction.AcceptRevisionSuggestion -> AppCommand.AcceptRevisionSuggestion(event.activityId, event.questionId, event.expectedEvidence)
        is LearningInteraction.ScheduleRevision -> AppCommand.ScheduleRevision(event.activityId, event.questionId, event.delayDays)
        is LearningInteraction.RecallResponse -> AppCommand.RecallResponse(event.activityId, event.expectedText, event.text)
        is LearningInteraction.RevealRecall -> AppCommand.RevealRecall(event.activityId)
        is LearningInteraction.RateRecall -> AppCommand.RateRecall(event.activityId, event.rating)
        is LearningInteraction.RestartRecall -> AppCommand.RestartRecall(event.activityId)
        is LearningInteraction.QuizQuestion -> AppCommand.QuizQuestion(event.activityId, event.questionId)
        is LearningInteraction.SaveAnnotationDraft -> AppCommand.SaveAnnotationDraft(event.activityId, event.draftId, event.draft)
        is LearningInteraction.CreateAnnotation -> AppCommand.CreateAnnotation(event.activityId, event.id, event.source, event.sentenceId, event.kind, event.text)
        is LearningInteraction.UpdateAnnotation -> AppCommand.UpdateAnnotation(event.activityId, event.id, event.expectedText, event.text)
        is LearningInteraction.RemoveAnnotation -> AppCommand.RemoveAnnotation(event.activityId, event.id, event.expectedText)
        is LearningInteraction.SelectAnswer -> AppCommand.SelectAnswer(event.activityId, event.questionId, event.option)
        is LearningInteraction.SubmitAnswer -> AppCommand.SubmitAnswer(event.activityId, event.questionId)
        is LearningInteraction.SetReadingPosition -> AppCommand.ReadingPosition(event.activityId, event.index, event.offset)
        is LearningInteraction.FocusSentence -> AppCommand.FocusSentence(event.activityId, event.sentenceId)
        is LearningInteraction.PinComponent -> AppCommand.Pin(event.componentId, event.pinned)
        is LearningInteraction.TransformDiagram -> AppCommand.Transform(event.activityId, event.zoom, event.panX, event.panY)
    }
}
